const r = $json;
const msg = String(r.rep_message || '');
const type = String(r.customer_type || '');
const diff = String(r.difficulty || '基礎');
const round = Number(r.round || 1);

function has(re){ return re.test(msg); }
function pick(arr, n){ return arr[Math.abs(n) % arr.length]; }

let resistance = 1;
if (diff === '中階') resistance = 2;
if (diff === '進階') resistance = 3;

let reply = '';
let customerMood = '觀望';
let objectiveReached = false;

// 客戶人格基礎反應
if (/理性|精算/.test(type)) {
  if (has(/數字|多少|差多少|費用|預算|報酬|成本|缺口/)) {
    reply = '可以，但我想先看到具體數字。你說的缺口到底怎麼算？';
    customerMood = '開始投入';
  } else if (has(/需求|擔心|希望|退休|家庭|現金流/)) {
    reply = '這些我知道，但我不想只聽概念。你能不能具體一點？';
  } else {
    reply = pick([
      '我比較重視數字，你先告訴我這件事實際差在哪裡。',
      '我不喜歡太多話術，你直接講重點跟成本。',
      '先不要談商品，我想知道這對我有什麼實際影響。'
    ], round);
  }
} else if (/防備|冷淡/.test(type)) {
  if (has(/不急|先了解|先幫您|不用現在決定/)) {
    reply = '好，那你先講重點，我時間不多。';
    customerMood = '防備下降';
  } else {
    reply = pick([
      '我現在很忙，有事直接講。',
      '保險我已經很多了，不用了吧。',
      '你是不是又要推產品？'
    ], round);
  }
} else if (/感性|家庭/.test(type)) {
  if (has(/家人|孩子|配偶|父母|照顧|擔心/)) {
    reply = '我最擔心的其實是如果我出事，家裡會亂掉。';
    customerMood = '情緒打開';
  } else {
    reply = pick([
      '我比較在意家人，不想讓他們以後辛苦。',
      '我其實不太懂保險，只想知道家裡會不會有保障。',
      '如果真的發生事情，我最怕拖累家人。'
    ], round);
  }
} else {
  if (has(/為什麼|最在意|最擔心|如果/)) {
    reply = '如果真的要說，我比較擔心未來現金流不夠。';
    customerMood = '願意分享';
  } else {
    reply = pick([
      '你先說說看。',
      '我還沒特別想過。',
      '這件事我有點興趣，但還不急。'
    ], round);
  }
}

// 異議注入
if (resistance >= 2 && round >= 2 && !/太貴|沒時間|再想想|已有保險/.test(msg)) {
  if (round % 3 === 0) {
    reply = '可是我覺得這類規劃最後通常都很貴，我想先再看看。';
    customerMood = '價格異議';
  }
}
if (resistance >= 3 && round >= 3 && round % 4 === 0) {
  reply = '我已經有保險了，而且最近也沒時間，我真的需要現在處理嗎？';
  customerMood = '複合異議';
}

// 是否達成下一步
if (has(/約|下次|哪一天|這週|下週|資料|盤點|20分鐘|30分鐘/) && round >= 3) {
  if (resistance === 1 || customerMood === '開始投入' || has(/不用現在決定|先盤點/)) {
    reply = '好，那你下週再找我，我可以先給你一些資料看看。';
    objectiveReached = true;
    customerMood = '願意下一步';
  }
}

const maxRounds = diff === '進階' ? 8 : diff === '中階' ? 6 : 5;
const ended = objectiveReached || round >= maxRounds;

return [{
  json: {
    ...r,
    customer_reply: reply,
    customer_mood: customerMood,
    objective_reached: objectiveReached,
    ended,
    next_round: round + 1,
    max_rounds: maxRounds
  }
}];

const r=$json;
const old=String(r.history||'').trim();
const newHistory = [
  old,
  `業務：${r.rep_message}`,
  `客戶：${r.customer_reply}`
].filter(Boolean).join('\n');

return [{json:{...r,updated_history:newHistory}}];

const r=$json;
const text=String(r.updated_history||'');

function count(re){ return (text.match(re)||[]).length; }
function cap(n){ return Math.max(0,Math.min(100,n)); }

let opening=50, questioning=40, needs=40, objection=40, closing=40;
if(/您好|哈囉|先生|小姐|哥|姐/.test(text)) opening+=10;
if(/不急著|先了解|先幫您|先盤點|不用現在決定/.test(text)) opening+=20;
const q=count(/[?？]/g); questioning+=Math.min(30,q*5);
if(/為什麼|怎麼看|比較在意|最擔心|如果/.test(text)) questioning+=15;
if(/家庭|孩子|配偶|父母/.test(text)) needs+=10;
if(/現金流|收入|支出|退休|資產|負擔/.test(text)) needs+=15;
if(/風險|擔心|缺口|影響/.test(text)) needs+=15;
if(/太貴|再想想|不需要|已有保險|沒時間|很忙/.test(text)) objection+=10;
if(/理解|我懂|可以理解|先不急/.test(text)) objection+=15;
if(/卡住的是|預算|時機|內容/.test(text)) objection+=20;
if(/下次|約|時間|資料|下一步|這週|下週/.test(text)) closing+=25;
if(r.objective_reached) closing+=20;

opening=cap(opening); questioning=cap(questioning); needs=cap(needs); objection=cap(objection); closing=cap(closing);
const total=Math.round(opening*.15+questioning*.25+needs*.25+objection*.20+closing*.15);
const scores={'開場':opening,'提問':questioning,'需求分析':needs,'異議處理':objection,'成交收口':closing};
const weakest=Object.entries(scores).sort((a,b)=>a[1]-b[1])[0];
const advice={
  '開場':'先降低客戶防備，清楚說明今天先了解、不急著談商品。',
  '提問':'增加開放式追問，避免連續自問自答。',
  '需求分析':'把問題連到家庭責任、現金流與未來目標。',
  '異議處理':'先確認異議真正原因，再回應。',
  '成交收口':'每次對話至少取得一個明確下一步。'
}[weakest[0]];

return [{json:{
  ...r,
  opening_score:opening,
  questioning_score:questioning,
  needs_score:needs,
  objection_score:objection,
  closing_score:closing,
  total_score:total,
  weakest_skill:weakest[0],
  improvement:advice,
  manager_required: total<65 || weakest[1]<55
}}];
